import base64
import json
from pathlib import Path
# Library to suppress warnings generated by your code:
import warnings

from langchain_openai import ChatOpenAI

# Codes to suppress warnings generated by your code:
def warn(*args, **kwargs):
    pass
warnings.warn = warn
warnings.filterwarnings('ignore')

### Load the json file. Define the loaded data as recipe_data.
with open(Path.home() / "food-chatbot-data" / "augmented_food_recipe.json") as json_file:
    recipe_data = json.load(json_file)

def vision_llm(system_msg, prompt_txt, image_path):
    #system_msg: input system message for the LLM
    #prompt_txt: input user prompt for the LLM
    #image_path: the file path of the input image

    ### Credentials of the model
    model_id = 'qwen2.5vl:3b'
    api_key = "ollama"
    url = "http://localhost:11434/v1"
    generate_params = {"max_tokens": 300}

    ### Define the model by ModelInference
    model = ChatOpenAI(
        model = model_id,
        api_key = api_key,
        base_url = url,
        extra_body = generate_params
    )    

    ### Encode the input image to a base64 string
    with open(image_path, "rb") as raw_bytes_open:
        raw_bytes = raw_bytes_open.read()
        base64_bytes = base64.b64encode(raw_bytes)
        base64_string = base64_bytes.decode()

    ### Define the messages for the model
    messages = [
        {
            "role": "system",
            "content": system_msg
        },
        {
            "role": "user",
            "content": [
                {"type": "text",
                 "text": prompt_txt
                },
                {
                    "type": "image_url",
                    "image_url": {
                        "url": f"data:image/png;base64,{base64_string}"
                    }
                }
            ]
        }
    ]

    ### Get the response for the messages 
    response = model.invoke(input = messages)
    return response.content

### Define the food image caption prompts given a food name.
### The food name, as you have noticed, comes from the corresponding recipe data.
### You want to include the food name to ensure the model focuses on it while giving captions.
def image_caption_prompt_template(food_name):
    # food_name: the food name of the recipe

    ### Design the prompts
    image_caption_system_msg = """
    Focus on relevant visual details, such as ingredients, cooking style, and presentation, while avoiding unnecessary or speculative information.
    """
    image_caption_prompt_txt = f"""
    Task:
    You are a helpful food-only assistant.
    
    Reliably convert the following food image of {food_name} into high-quality textual description in 1 or 2 sentences:
    """

    return image_caption_system_msg, image_caption_prompt_txt

### Get captions for each image in the dataset and add to the JSON file (up tp 15 minutes)
### recipe_data is the recipe you loaded
for i in range(len(recipe_data)):
    if (i+1)%20 == 0:
        print(f'{i+1} out of {len(recipe_data)} is done')

    ### Get the caption prompts
    image_caption_system_msg, image_caption_prompt_txt = image_caption_prompt_template(recipe_data[i]["name"])

    ### Get the response with the prompts
    response = vision_llm(image_caption_system_msg, image_caption_prompt_txt, Path.home() / "food-chatbot-data" / "recipe_images" / "synthetic_recipe_images" / f"recipe{i + 1}.png")

    ### Save the response as another item in the recipe data
    recipe_data[i]['image_description'] = response
print('ALL DONE!')

filename = Path.home() / "food-chatbot-data" / "augmented_food_recipe.json"
with open(filename, 'w', encoding='utf-8') as f:
    json.dump(recipe_data, f, indent=4)